            "config_error_lines": config_error_lines[:MAX_ERROR_EXAMPLES],
            "blocking_diagnostics": blocking_diagnostics[:MAX_ERROR_EXAMPLES],
            "database141_lines": database141_lines[:MAX_ERROR_EXAMPLES],
